mapper.sql:
tenant_id = #{tenantId}

    AND knowledge_base_id = #{knowledgeBaseId}


    AND status = #{status}


    AND priority = #{priority}


    AND assignee_id = #{assigneeId}


    AND due_at IS NOT NULL
    AND due_at < CURRENT_TIMESTAMP(6)
    AND status NOT IN ('RESOLVED', 'CLOSED')


    AND (
        ticket_no LIKE CONCAT('%', #{keyword}, '%')
        OR customer_name LIKE CONCAT('%', #{keyword}, '%')
        OR issue_summary LIKE CONCAT('%', #{keyword}, '%')
        OR customer_question LIKE CONCAT('%', #{keyword}, '%')
        OR COALESCE(order_no, '') LIKE CONCAT('%', #{keyword}, '%')
        OR COALESCE(product_name, '') LIKE CONCAT('%', #{keyword}, '%')
    )
